-- Refer to https://wiki.hypr.land/Configuring/Basics/Variables/
hl.config({
    general = {
        gaps_in  = 5,
        gaps_out = 20,

        border_size = 2,

        col = {
            active_border = {
                colors = {
                    "rgba(" .. wallColors.accent  .. "ee)",
                    "rgba(" .. wallColors.accent2 .. "ee)",
                },
                angle = 45,
            },
            inactive_border = "rgba(595959aa)",
        },

        -- Set to true to enable resizing windows by clicking and dragging on borders and gaps
        resize_on_border = false,

        -- Please see https://wiki.hypr.land/Configuring/Advanced-and-Cool/Tearing/ before you turn this on
        allow_tearing = false,

        layout = "dwindle",
    },

    decoration = {
        -- 10, and this one is set from the OUTSIDE in. Applications draw
        -- their own rounded corner for the content inside the window, and at
        -- 24 the compositor's curve was visibly rounder than the app's, so
        -- every window showed two disagreeing arcs nested in one another.
        -- Measured on Zen's content area (grim over the window, first light
        -- pixel per row, from y=8 x=200 to y=17 x=191): the curve spans
        -- ~10 px. So this is not a taste setting, it is the radius the
        -- applications already use.
        --
        -- Quickshell uses the same figure for the rounded screen corners and
        -- for the fillet where the bar meets the sides (Theme.qml:
        -- screenCornerRadius / barCornerRadius). Those three are one
        -- decision, not three: they are the radii that touch each other on
        -- screen. Change all three together or the edges stop agreeing.
        --
        -- What this costs, because the history below is real and going back
        -- down is not free: a concave fillet has only as many pixel rows as
        -- its radius to spread its antialiasing over, so the bar fillet at
        -- 10 shades more coarsely than at 24. That is the price paid to kill
        -- the double arc on every window. If the fillet ever reads jagged,
        -- this is why, and the fix is a bigger radius in all three places.
        --
        -- History: 10 -> 16 (to line up with Quickshell) -> 24 (to settle
        -- the jagged fillets) -> 10 (to match the applications).
        rounding       = 10,
        rounding_power = 2,

        -- Change transparency of focused and unfocused windows
        active_opacity   = 1.0,
        inactive_opacity = 1.0,

        shadow = {
            enabled      = true,
            range        = 4,
            render_power = 3,
            color        = 0xee1a1a1a,
        },

        -- "Glass" effect: Hyprland applies the blur behind any transparent
        -- window (kitty runs at background_opacity 0.70).
        --
        --   size   = blur radius. Higher = softer.
        --   passes = how many times it repeats. This is what turns a faint
        --            veil into actual frosted glass. Beyond 4 it is barely
        --            noticeable and costs GPU.
        blur = {
            enabled = true,

            -- 14, up from 8, for a frostier glass behind Zen's sidebar.
            -- `size` is the only lever available for that: `passes` is
            -- pinned at 2 for edge quality (measured, see below), so making
            -- the backdrop softer has to come from the radius.
            --
            -- CAREFUL, this is GLOBAL. It is not a browser setting: every
            -- translucent surface gets it -- kitty at background_opacity
            -- 0.70, the Quickshell bar, the notification panel, popups. It
            -- was raised alongside Zen's own tint going 0.72 -> 0.85
            -- (userChrome.css, --zen-background-opacity), which is the pair
            -- that produces "glass" rather than "see-through": more blur
            -- behind, less wallpaper coming through the tint. If the
            -- terminal ever looks mushy behind its text, this is the number.
            size    = 14,

            -- 2 AND NOT 3, and the reason is edge quality rather than taste.
            --
            -- Each pass halves the resolution the blur is computed at, so at
            -- 3 the backdrop is sampled 8x coarser than the screen. Where a
            -- shell surface has an ANTIALIASED curved edge, its partially
            -- transparent pixels blend with that coarse backdrop, and the
            -- gradient that makes the curve look smooth turns into steps --
            -- the jagged corners that took a whole session to pin down.
            --
            -- Measured on the notification panel's bottom-right corner over a
            -- bright window, in intermediate pixels per row (more is
            -- smoother): passes 3 -> 1.58, passes 1 -> 3.00, passes 2 -> 4.04,
            -- which equals turning the blur off entirely. So 2 costs nothing
            -- visually and fixes the edges.
            passes  = 2,

            -- Subtle grain: breaks the banding (colour stepping) that blur
            -- leaves over wallpaper gradients.
            noise = 0.0117,

            -- Darkens and lowers the contrast of what is behind, so the
            -- terminal's light text stays readable over bright wallpapers.
            contrast   = 0.9,
            brightness = 0.8,

            -- Saturates the colours of the blurred background (macOS style).
            vibrancy          = 0.1696,
            vibrancy_darkness = 0.0,

            -- Blur context menus and popups too.
            popups       = true,
            popups_ignorealpha = 0.2,

            -- xray = true blurs only the wallpaper, ignoring the windows
            -- underneath. Cleaner and cheaper, but you lose the sense of
            -- stacked layers. Try it if your GPU struggles with passes = 3.
            xray = false,
        },
    },

    animations = {
        enabled = true,
    },
})

-- Default curves and animations, see https://wiki.hypr.land/Configuring/Advanced-and-Cool/Animations/
hl.curve("easeOutQuint",   { type = "bezier", points = { {0.23, 1},    {0.32, 1}    } })
hl.curve("easeInOutCubic", { type = "bezier", points = { {0.65, 0.05}, {0.36, 1}    } })
hl.curve("linear",         { type = "bezier", points = { {0, 0},       {1, 1}       } })
hl.curve("almostLinear",   { type = "bezier", points = { {0.5, 0.5},   {0.75, 1}    } })
hl.curve("quick",          { type = "bezier", points = { {0.15, 0},    {0.1, 1}     } })

-- Default springs
hl.curve("easy",           { type = "spring", mass = 1, stiffness = 238.1191, dampening = 24.21279333 })

hl.animation({ leaf = "global",        enabled = true,  speed = 10,   bezier = "default" })
hl.animation({ leaf = "border",        enabled = true,  speed = 5.39, bezier = "easeOutQuint" })
hl.animation({ leaf = "windows",       enabled = true,  speed = 4.79, spring = "easy" })
hl.animation({ leaf = "windowsIn",     enabled = true,  speed = 4.1,  spring = "easy",         style = "popin 87%" })
hl.animation({ leaf = "windowsOut",    enabled = true,  speed = 1.49, bezier = "linear",       style = "popin 87%" })
hl.animation({ leaf = "fadeIn",        enabled = true,  speed = 1.73, bezier = "almostLinear" })
hl.animation({ leaf = "fadeOut",       enabled = true,  speed = 1.46, bezier = "almostLinear" })
hl.animation({ leaf = "fade",          enabled = true,  speed = 3.03, bezier = "quick" })
hl.animation({ leaf = "layers",        enabled = true,  speed = 3.81, bezier = "easeOutQuint" })
hl.animation({ leaf = "layersIn",      enabled = true,  speed = 4,    bezier = "easeOutQuint", style = "fade" })
hl.animation({ leaf = "layersOut",     enabled = true,  speed = 1.5,  bezier = "linear",       style = "fade" })
hl.animation({ leaf = "fadeLayersIn",  enabled = true,  speed = 1.79, bezier = "almostLinear" })
hl.animation({ leaf = "fadeLayersOut", enabled = true,  speed = 1.39, bezier = "almostLinear" })
-- Horizontal slide when switching workspace. Other possible styles:
-- "slidevert" (vertical), "slidefade 20%" (slide and fade), "fade".
hl.animation({ leaf = "workspaces",    enabled = true,  speed = 4,    bezier = "easeOutQuint", style = "slide" })
hl.animation({ leaf = "workspacesIn",  enabled = true,  speed = 4,    bezier = "easeOutQuint", style = "slide" })
hl.animation({ leaf = "workspacesOut", enabled = true,  speed = 4,    bezier = "easeOutQuint", style = "slide" })
hl.animation({ leaf = "zoomFactor",    enabled = true,  speed = 7,    bezier = "quick" })

