-- See https://wiki.hypr.land/Configuring/Basics/Window-Rules/
-- and https://wiki.hypr.land/Configuring/Basics/Workspace-Rules/

-- Example window rules that are useful

local suppressMaximizeRule = hl.window_rule({
    -- Ignore maximize requests from all apps. You'll probably like this.
    name  = "suppress-maximize-events",
    match = { class = ".*" },

    suppress_event = "maximize",
})
-- suppressMaximizeRule:set_enabled(false)

hl.window_rule({
    -- Fix some dragging issues with XWayland
    name  = "fix-xwayland-drags",
    match = {
        class      = "^$",
        title      = "^$",
        xwayland   = true,
        float      = true,
        fullscreen = false,
        pin        = false,
    },

    no_focus = true,
})

-- Layer rules also return a handle.
-- local overlayLayerRule = hl.layer_rule({
--     name  = "no-anim-overlay",
--     match = { namespace = "^my-overlay$" },
--     no_anim = true,
-- })
-- overlayLayerRule:set_enabled(false)


-- Blur for the Quickshell bar under trial on the portrait monitor.
-- Its namespace is set in QML, not by the process name: see
-- WlrLayershell.namespace in ~/.config/quickshell/modules/bar/Bar.qml.
-- Remove this rule together with the quickshell stow package if the trial
-- does not end in a migration.
hl.layer_rule({
    name  = "blur-quickshell",
    -- The popouts, the notification panel and the power menu share the bar's
    -- glass, so they share its blur. Screen corners are opaque black and
    -- deliberately left out.
    --
    -- Anything quickshell puts on screen with a glass surface has to be named
    -- here. A namespace that is NOT matched does not come out unblurred -- it
    -- falls through to the GLOBAL decoration.blur, which has different
    -- parameters and no xray, and the surface ends up visibly blurrier than
    -- the bar it is supposed to belong to. That is how the power menu looked
    -- before it was added to this list.
    match = { namespace = "^quickshell-(bar|popout|notifications|powermenu|launcher|cheatsheet)$" },

    blur          = true,

    -- 0.84: JUST UNDER the surfaces' own alpha (Theme.glassAlpha = 0.85).
    -- These two numbers are tied; move one and move the other.
    --
    -- Hyprland blurs the WHOLE rectangle of a layer surface. It has no idea
    -- the shell drew a rounded corner inside it, so the blur carries on into
    -- the transparent area outside the curve and juts out past the edge --
    -- the sawtooth sticking out beyond the border. ignore_alpha is what
    -- excludes pixels from the blur: at 0 (what was here) nothing is
    -- excluded and the whole corner bleeds; just below the fill's alpha, only
    -- the solid interior gets blurred and the antialiased edge is left alone.
    --
    -- It is not enough on its own: with passes at 3 the corner steps again
    -- whatever this is set to. Both changes are needed.
    ignore_alpha  = 0.84,
    blur_popups   = true,

    -- xray makes the blur sample ONLY the wallpaper, ignoring the windows in
    -- between. Without it the bar and its popouts are the same colour in the
    -- config and different colours on screen: the bar sits over the
    -- wallpaper, a popout hangs over whatever window is below it, and a
    -- surface at 85% opacity shows what is behind it. Measured: bar
    -- rgb(39,44,37) against popout rgb(25,28,25). With xray both composite
    -- over the same wallpaper and match.
    xray = true,
})


-- The blur-dunst rule was here. It matched the namespace "notifications",
-- which was dunst's layer; Quickshell's panel calls itself
-- "quickshell-notifications" and is covered by blur-quickshell above.
-- Nothing on this system creates a bare "notifications" layer any more.

-- Hyprland-run windowrule
hl.window_rule({
    name  = "move-hyprland-run",
    match = { class = "hyprland-run" },

    move  = "20 monitor_h-120",
    float = true,
})

-- Helper apps kept out of the tiling: they are opened briefly and closed,
-- and tiled they would reshuffle the rest of the workspace on every launch.
--
-- The classes are the ones reported by `hyprctl clients`, NOT the
-- StartupWMClass from the .desktop: the two do not always match.

-- Nautilus, the graphical file manager (SUPER + E).
--
-- Transparency is the only part of the look that does NOT come from GTK:
-- libadwaita paints its background opaque and there is no way to ask it for
-- an alpha from user CSS, so the compositor provides it. The blur does not
-- need declaring -- decoration.blur is already globally enabled and Hyprland
-- applies it behind any translucent window, same as with kitty.
--
-- CAREFUL: opacity affects the WHOLE window, text and icons included.
-- 0.82 is the point where the glass reads without file names fighting the
-- wallpaper. Go lower and label text starts losing contrast over images with
-- bright detail; the blur already ships with brightness 0.8 to compensate,
-- but there is a limit.
--
-- And CAREFUL with the SYNTAX, which here is not what you would expect from
-- a Lua config: opacity is a TEXT field with hyprlang grammar --
-- "active inactive fullscreen", the last two optional. There is no
-- opacity_inactive field, a bare number per state is not accepted, and
-- neither is a table { active =, inactive = }: the parser rejects all three
-- with "field 'opacity': string type requires a string".
--
-- Worse: `hyprctl reload` answers "ok" anyway and the rule is silently
-- dropped. The error only shows through `hyprctl configerrors` and in the
-- red banner in the corner. If you touch this, check with configerrors, not
-- with the exit code.
hl.window_rule({
    name  = "float-nautilus",
    match = { class = "^org\\.gnome\\.Nautilus$" },

    float  = true,
    size   = "1400 850",
    center = true,

    -- Both values identical, and that is the point: the second one is the
    -- INACTIVE opacity, and at 0.74 the window visibly changed colour the
    -- moment it lost focus. Worse than a uniform dim: the sidebar and the
    -- content pane are different widgets sitting over different parts of
    -- the blurred wallpaper, so the same drop in alpha moved them by
    -- different amounts and the chrome stopped matching itself.
    -- The GTK side of this is in the gtk4-colors.css template, where every
    -- *_backdrop_color equals its bg colour for the same reason. Changing
    -- one without the other brings the mismatch back.
    opacity = "0.82 0.82",
})

-- Loupe (images) and Celluloid (video) replaced gwenview and haruna. The
-- reason was the same one that pushed out Dolphin: both linked
-- libKF6ColorScheme, which forces BreezeDark on the app over the platform
-- theme, so they stayed grey while the rest of the desktop followed the
-- wallpaper.
--
-- Both are GTK4/libadwaita, meaning they read ~/.config/gtk-4.0/gtk.css just
-- like Nautilus and need no new template.
--
-- NO opacity here, unlike Nautilus, and that is deliberate: opacity in
-- Hyprland affects the whole window, content included. In an image viewer
-- and a media player that means blending the wallpaper into the picture you
-- are looking at -- goodbye blacks and any colour judgement. The glass is
-- for the chrome, not for the content.
hl.window_rule({
    name  = "float-loupe",
    match = { class = "^org\\.gnome\\.Loupe$" },

    float  = true,
    size   = "1400 850",
    center = true,
})

hl.window_rule({
    name  = "float-celluloid",
    match = { class = "^io\\.github\\.celluloid_player\\.Celluloid$" },

    float  = true,
    size   = "1280 720",   -- 16:9, so it does not come up letterboxed
    center = true,
})

-- zathura, the PDF reader.
--
-- Fixed "size" with A4 portrait proportions (850/1180 = 0.72, A4 is 0.707).
-- Measured: zathura does NOT request a size matching the document. With an
-- A4 portrait (ratio 0.71) it opens at 1252x952 and with a landscape one
-- (1.41) at 804x617 -- both windows land at ratio ~1.30, unrelated to the
-- page. So without a fixed size you get a landscape window for a portrait
-- document and wasted background on the sides.
--
-- Hyprland cannot measure the content either: it only sees what the window
-- asks for. Fitting it properly would need reading the page dimensions with
-- pdfinfo before opening and resizing afterwards.
--
-- 1180 of height fits DP-3 (1440) leaving room for the bar.
hl.window_rule({
    name  = "float-zathura",
    match = { class = "^org\\.pwmt\\.zathura$" },

    float  = true,
    size   = "850 1180",
    center = true,
})

-- satty, the annotation editor that SUPER+SHIFT+S pipes the screenshot into
-- (see the screenshot section above).
--
-- No "size" on purpose: the window fits the screenshot, and forcing a fixed
-- measure would distort the canvas depending on whether you grabbed a small
-- region or a whole monitor.
--
-- But "max_size" IS needed: satty asks for a window the size of the image,
-- so capturing a whole monitor (or opening a large image) pushes it off
-- screen and the buttons at the bottom end up out of reach. The cap fits
-- DP-3 leaving room for the bar.
hl.window_rule({
    name  = "float-satty",
    match = { class = "^com\\.gabm\\.satty$" },

    float    = true,
    max_size = "2400 1300",
    center   = true,
})


